const { useEffect, useRef, useState } = React;

// 画布框架：按 DPR 设置像素尺寸、跟随宽度重绘、切换主题时重绘；坐标单位为 CSS 像素
const useCanvas = (draw, deps) => {
  const ref = useRef(null);
  const { color } = useTokens();
  // 重绘函数每次渲染更新，尺寸监听只建立一次，动画逐帧重绘时不重复创建观察器
  const renderRef = useRef(() => {});
  renderRef.current = () => {
    const canvas = ref.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = canvas.getBoundingClientRect();
    const pixelWidth = Math.round(width * dpr);
    const pixelHeight = Math.round(height * dpr);
    // 重设尺寸会清空并重新分配画布，只在尺寸真正变化时才做
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    ctx.save();
    draw(ctx, { width, height, dpr, color });
    ctx.restore();
  };
  useEffect(() => renderRef.current(), [color, ...deps]);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const observer = new ResizeObserver(() => renderRef.current());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, []);
  return ref;
};

// 画布上的标注文字：等宽字体、次要墨色
const note = (ctx, color, text, x, y, align = "left") => {
  ctx.save();
  ctx.font = `12px ${color("font-mono")}`;
  ctx.fillStyle = color("ink-3");
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
  ctx.restore();
};

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 20px 20px;
      background-position: 10px 10px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Stage = ({ canvasRef, height, className = "" }) => (
  <canvas
    ref={canvasRef}
    className={`cb-grid block w-full rounded-tau-md border border-line-1 ${className}`}
    style={{ height }}
  />
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Demo = ({ children }) => (
  <div className="flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    {children}
  </div>
);

const Row = ({ children }) => <div className="flex flex-wrap items-center gap-x-6 gap-y-3">{children}</div>;

// 在画布上拖拽控制点：按下时选中 14px 内最近的点，拖动时更新坐标
const useDraggablePoints = (canvasRef, points, setPoints) => {
  const activeRef = useRef(-1);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const locate = event => {
      const rect = canvas.getBoundingClientRect();
      return { x: event.clientX - rect.left, y: event.clientY - rect.top, rect };
    };
    const down = event => {
      const { x, y } = locate(event);
      const index = points.findIndex(point => Math.hypot(point.x - x, point.y - y) < 14);
      if (index < 0) return;
      activeRef.current = index;
      canvas.setPointerCapture(event.pointerId);
    };
    const move = event => {
      const { x, y, rect } = locate(event);
      const hovering = points.some(point => Math.hypot(point.x - x, point.y - y) < 14);
      canvas.style.cursor = activeRef.current >= 0 ? "grabbing" : hovering ? "grab" : "";
      if (activeRef.current < 0) return;
      const clamp = (value, max) => Math.min(Math.max(value, 6), max - 6);
      const next = { x: clamp(x, rect.width), y: clamp(y, rect.height) };
      setPoints(list => list.map((point, index) => (index === activeRef.current ? { ...point, ...next } : point)));
    };
    const up = () => {
      activeRef.current = -1;
    };
    canvas.addEventListener("pointerdown", down);
    canvas.addEventListener("pointermove", move);
    canvas.addEventListener("pointerup", up);
    canvas.addEventListener("pointercancel", up);
    return () => {
      canvas.removeEventListener("pointerdown", down);
      canvas.removeEventListener("pointermove", move);
      canvas.removeEventListener("pointerup", up);
      canvas.removeEventListener("pointercancel", up);
    };
  }, [points]);
};

// 控制点：实心圆点加名称
const handle = (ctx, color, point, name, token = "accent") => {
  ctx.save();
  ctx.fillStyle = color("bg-surface");
  ctx.strokeStyle = color(token);
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(point.x, point.y, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.restore();
  note(ctx, color, name, point.x + 10, point.y - 10);
};

// 用参数方程逐段逼近曲线（与 Canvas 内置 API 结果一致）
const sample = (points, t) => {
  if (points.length === 1) return points[0];
  const next = [];
  for (let i = 0; i < points.length - 1; i++) {
    next.push({ x: points[i].x + (points[i + 1].x - points[i].x) * t, y: points[i].y + (points[i + 1].y - points[i].y) * t });
  }
  return sample(next, t);
};

const NAMES = ["起点", "控制点", "终点"];

const Component = () => {
  const [points, setPoints] = useState([{ x: 60, y: 150 }, { x: 180, y: 30 }, { x: 300, y: 150 }]);
  const [t, setT] = useState(0.5);
  const ref = useCanvas((ctx, { color }) => {
    // 控制多边形：首尾两段即曲线在起点、终点处的切线
    ctx.save();
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = color("line-1");
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    points.forEach((point, index) => (index ? ctx.lineTo(point.x, point.y) : ctx.moveTo(point.x, point.y)));
    ctx.stroke();
    ctx.restore();
    ctx.beginPath();
    ctx.lineWidth = 3;
    ctx.strokeStyle = color("accent");
    for (let step = 0; step <= 100; step++) {
      const point = sample(points, step / 100);
      if (step === 0) ctx.moveTo(point.x, point.y);
      else ctx.lineTo(point.x, point.y);
    }
    ctx.stroke();
    const current = sample(points, t);
    ctx.beginPath();
    ctx.fillStyle = color("accent");
    ctx.arc(current.x, current.y, 4, 0, Math.PI * 2);
    ctx.fill();
    points.forEach((point, index) => handle(ctx, color, point, NAMES[index], index === 0 || index === points.length - 1 ? "tag-1" : "tag-3"));
  }, [points, t]);
  useDraggablePoints(ref, points, setPoints);

  return (
    <Demo>
      <Stage canvasRef={ref} height={220} className="touch-none" />
      <Row>
        <Slider label="t" value={t} min={0} max={1} step={0.01} onChange={setT} format={value => value.toFixed(2)} />
        <Chip>quadraticCurveTo(cx, cy, x, y)</Chip>
      </Row>
      <span className="text-tau-meta text-ink-3">拖动控制点改变曲线；实心点是参数 t 对应的位置</span>
    </Demo>
  );
};

